import React, { useState, useEffect } from 'react';
import { useParams, useHistory } from 'react-router-dom';
import { 
    Container, 
    Card, 
    Row, 
    Col, 
    Badge, 
    Button, 
    Table, 
    Modal, 
    Alert, 
    Spinner,
    Tabs,
    Tab,
    ListGroup
} from 'react-bootstrap';
import { 
    getUserInfo, 
    getSellerInfo, 
    blockUser, 
    unblockUser,
    deleteUser 
} from '../http/userAPI';
import { getSellerProducts } from '../http/deviceAPI';

const AdminUserDetail = () => {
    const { id } = useParams();
    const history = useHistory();
    const [user, setUser] = useState(null);
    const [seller, setSeller] = useState(null);
    const [products, setProducts] = useState([]);
    const [reviews, setReviews] = useState([]);
    const [messages, setMessages] = useState([]);
    const [loading, setLoading] = useState(true);
    const [actionLoading, setActionLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');
    const [deleteModal, setDeleteModal] = useState({ show: false, type: '', id: null });

    useEffect(() => {
        loadUserData();
    }, [id]);

    const loadUserData = async () => {
        setLoading(true);
        try {
            // Загружаем информацию о пользователе
            const userData = await getUserInfo(id);
            setUser(userData);

            // Загружаем информацию о продавце
            if (userData.Seller) {
                const sellerData = await getSellerInfo(userData.Seller.id);
                setSeller(sellerData);

                // Загружаем товары продавца
                const productsData = await getSellerProducts(userData.Seller.id);
                setProducts(productsData);
            }

            // Здесь можно добавить загрузку отзывов и сообщений
            // setReviews(reviewsData);
            // setMessages(messagesData);

        } catch (e) {
            setError('Ошибка при загрузке данных пользователя: ' + (e.response?.data?.message || e.message));
        } finally {
            setLoading(false);
        }
    };

    const handleBlockUser = async () => {
        setActionLoading(true);
        try {
            await blockUser(id);
            setSuccess('Пользователь заблокирован');
            loadUserData(); // Обновляем данные
        } catch (e) {
            setError('Ошибка при блокировке: ' + (e.response?.data?.message || e.message));
        } finally {
            setActionLoading(false);
        }
    };

    const handleUnblockUser = async () => {
        setActionLoading(true);
        try {
            await unblockUser(id);
            setSuccess('Пользователь разблокирован');
            loadUserData(); // Обновляем данные
        } catch (e) {
            setError('Ошибка при разблокировке: ' + (e.response?.data?.message || e.message));
        } finally {
            setActionLoading(false);
        }
    };

    const handleDeleteProduct = async (productId) => {
        setActionLoading(true);
        try {
            // Здесь нужно добавить метод deleteProduct в API
            // await deleteProduct(productId);
            setSuccess('Товар удален');
            setDeleteModal({ show: false, type: '', id: null });
            loadUserData(); // Обновляем данные
        } catch (e) {
            setError('Ошибка при удалении товара: ' + (e.response?.data?.message || e.message));
        } finally {
            setActionLoading(false);
        }
    };

    const handleDeleteReview = async (reviewId) => {
        setActionLoading(true);
        try {
            // Здесь нужно добавить метод deleteReview в API
            // await deleteReview(reviewId);
            setSuccess('Отзыв удален');
            setDeleteModal({ show: false, type: '', id: null });
            loadUserData(); // Обновляем данные
        } catch (e) {
            setError('Ошибка при удалении отзыва: ' + (e.response?.data?.message || e.message));
        } finally {
            setActionLoading(false);
        }
    };

    const openDeleteModal = (type, itemId) => {
        setDeleteModal({ show: true, type, id: itemId });
    };

    if (loading) {
        return (
            <Container className="mt-4 d-flex justify-content-center">
                <Spinner animation="border" role="status">
                    <span className="visually-hidden">Загрузка...</span>
                </Spinner>
            </Container>
        );
    }

    if (!user) {
        return (
            <Container className="mt-4">
                <Alert variant="danger">Пользователь не найден</Alert>
            </Container>
        );
    }

    return (
        <Container className="mt-4">
            {/* Заголовок и кнопки управления */}
            <div className="d-flex justify-content-between align-items-center mb-4">
                <div>
                    <h2>Пользователь: {user.username}</h2>
                    <div className="d-flex gap-2 mt-2">
                        <Badge bg={user.role === 'ADMIN' ? 'danger' : 'primary'}>
                            {user.role}
                        </Badge>
                        <Badge bg={user.is_blocked ? 'danger' : 'success'}>
                            {user.is_blocked ? 'Заблокирован' : 'Активен'}
                        </Badge>
                    </div>
                </div>
                <div className="d-flex gap-2">
                    <Button 
                        variant="outline-secondary"
                        onClick={() => history.push('/admin/users')}
                    >
                        ← Назад к списку
                    </Button>
                    {!user.is_blocked ? (
                        <Button 
                            variant="outline-warning"
                            onClick={handleBlockUser}
                            disabled={actionLoading}
                        >
                            {actionLoading ? <Spinner size="sm" /> : '🔒 Заблокировать'}
                        </Button>
                    ) : (
                        <Button 
                            variant="outline-success"
                            onClick={handleUnblockUser}
                            disabled={actionLoading}
                        >
                            {actionLoading ? <Spinner size="sm" /> : '🔓 Разблокировать'}
                        </Button>
                    )}
                </div>
            </div>

            {error && <Alert variant="danger">{error}</Alert>}
            {success && <Alert variant="success">{success}</Alert>}

            <Tabs defaultActiveKey="userInfo" className="mb-3">
                {/* Вкладка с информацией о пользователе */}
                <Tab eventKey="userInfo" title="Информация о пользователе">
                    <Row>
                        <Col md={6}>
                            <Card>
                                <Card.Header>
                                    <h5 className="mb-0">Основная информация</h5>
                                </Card.Header>
                                <Card.Body>
                                    <ListGroup variant="flush">
                                        <ListGroup.Item>
                                            <strong>ID:</strong> {user.id}
                                        </ListGroup.Item>
                                        <ListGroup.Item>
                                            <strong>Имя пользователя:</strong> {user.username}
                                        </ListGroup.Item>
                                        <ListGroup.Item>
                                            <strong>Email:</strong> {user.email}
                                        </ListGroup.Item>
                                        <ListGroup.Item>
                                            <strong>Телефон:</strong> {user.phone || 'Не указан'}
                                        </ListGroup.Item>
                                        <ListGroup.Item>
                                            <strong>Дата регистрации:</strong> {new Date(user.createdAt).toLocaleString('ru-RU')}
                                        </ListGroup.Item>
                                    </ListGroup>
                                </Card.Body>
                            </Card>
                        </Col>
                        <Col md={6}>
                            <Card>
                                <Card.Header>
                                    <h5 className="mb-0">Информация о продавце</h5>
                                </Card.Header>
                                <Card.Body>
                                    {seller ? (
                                        <ListGroup variant="flush">
                                            <ListGroup.Item>
                                                <strong>ID продавца:</strong> {seller.id}
                                            </ListGroup.Item>
                                            <ListGroup.Item>
                                                <strong>Название магазина:</strong> {seller.name}
                                            </ListGroup.Item>
                                            <ListGroup.Item>
                                                <strong>Рейтинг:</strong> {seller.rating || 'Нет рейтинга'}
                                            </ListGroup.Item>
                                            <ListGroup.Item>
                                                <strong>Описание:</strong> {seller.description || 'Нет описания'}
                                            </ListGroup.Item>
                                            {seller.img && (
                                                <ListGroup.Item>
                                                    <strong>Изображение:</strong><br />
                                                    <img 
                                                        src={seller.img} 
                                                        alt="Seller" 
                                                        style={{ maxWidth: '200px', maxHeight: '200px' }}
                                                    />
                                                </ListGroup.Item>
                                            )}
                                        </ListGroup>
                                    ) : (
                                        <p className="text-muted">Пользователь не является продавцом</p>
                                    )}
                                </Card.Body>
                            </Card>
                        </Col>
                    </Row>
                </Tab>

                {/* Вкладка с товарами */}
                <Tab eventKey="products" title={`Товары (${products.length})`}>
                    <Card>
                        <Card.Header>
                            <h5 className="mb-0">Товары продавца</h5>
                        </Card.Header>
                        <Card.Body>
                            {products.length > 0 ? (
                                <Table striped bordered hover>
                                    <thead>
                                        <tr>
                                            <th>ID</th>
                                            <th>Название</th>
                                            <th>Город</th>
                                            <th>Цена</th>
                                            <th>Тип цены</th>
                                            <th>Статус</th>
                                            <th>Действия</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {products.map(product => (
                                            <tr key={product.id}>
                                                <td>{product.id}</td>
                                                <td>{product.name}</td>
                                                <td>{product.city}</td>
                                                <td>{product.price || product.price_text}</td>
                                                <td>
                                                    <Badge bg="info">
                                                        {product.price_type === 'fixed' ? 'Фиксированная' : 'Договорная'}
                                                    </Badge>
                                                </td>
                                                <td>
                                                    <Badge bg={product.is_hidden ? 'secondary' : 'success'}>
                                                        {product.is_hidden ? 'Скрыт' : 'Активен'}
                                                    </Badge>
                                                </td>
                                                <td>
                                                    <Button
                                                        variant="outline-danger"
                                                        size="sm"
                                                        onClick={() => openDeleteModal('product', product.id)}
                                                        disabled={actionLoading}
                                                    >
                                                        🗑️ Удалить
                                                    </Button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </Table>
                            ) : (
                                <p className="text-muted">У пользователя нет товаров</p>
                            )}
                        </Card.Body>
                    </Card>
                </Tab>

                {/* Вкладка с отзывами (заглушка) */}
                <Tab eventKey="reviews" title="Отзывы (0)">
                    <Card>
                        <Card.Header>
                            <h5 className="mb-0">Отзывы пользователя</h5>
                        </Card.Header>
                        <Card.Body>
                            <p className="text-muted">Функциональность отзывов будет добавлена позже</p>
                        </Card.Body>
                    </Card>
                </Tab>

                {/* Вкладка с сообщениями (заглушка) */}
                <Tab eventKey="messages" title="Сообщения (0)">
                    <Card>
                        <Card.Header>
                            <h5 className="mb-0">Сообщения пользователя</h5>
                        </Card.Header>
                        <Card.Body>
                            <p className="text-muted">Функциональность сообщений будет добавлена позже</p>
                        </Card.Body>
                    </Card>
                </Tab>
            </Tabs>

            {/* Модальное окно удаления */}
            <Modal show={deleteModal.show} onHide={() => setDeleteModal({ show: false, type: '', id: null })}>
                <Modal.Header closeButton>
                    <Modal.Title>Подтверждение удаления</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    Вы уверены, что хотите удалить {deleteModal.type === 'product' ? 'товар' : 'отзыв'}?
                    Это действие нельзя отменить.
                </Modal.Body>
                <Modal.Footer>
                    <Button 
                        variant="secondary" 
                        onClick={() => setDeleteModal({ show: false, type: '', id: null })}
                        disabled={actionLoading}
                    >
                        Отмена
                    </Button>
                    <Button 
                        variant="danger" 
                        onClick={() => deleteModal.type === 'product' ? handleDeleteProduct(deleteModal.id) : handleDeleteReview(deleteModal.id)}
                        disabled={actionLoading}
                    >
                        {actionLoading ? (
                            <>
                                <Spinner size="sm" className="me-2" />
                                Удаление...
                            </>
                        ) : (
                            'Удалить'
                        )}
                    </Button>
                </Modal.Footer>
            </Modal>
        </Container>
    );
};

